create or replace function private.t_app_biu() returns trigger language plpgsql security definer set search_path to 'pg_catalog','api' as $function$
declare o int; n int; lim numeric; used numeric; r text := current_user;
begin
 n := private.ord(new.status_id);
 if n is null then raise exception 'unknown status'; end if;
 if tg_op='INSERT' then
   if n<>1 then raise exception 'new application must be in status Черновик'; end if;
 else
   o := private.ord(old.status_id);
   if n<>o then
     if n<>o+1 and not (o=3 and n=5) then raise exception 'status transition not allowed'; end if;
     if r='applicant' and not (o=1 and n=2) then raise exception 'applicant may only submit a draft'; end if;
     if r='expert' and not (o in (2,3)) then raise exception 'expert may not make this transition'; end if;
   end if;
 end if;
 if n=4 then
   select funding_limit into lim from api.company where id=new.company_id for update;
   select coalesce(sum(a.amount),0) into used from api.application a
     where a.company_id=new.company_id and private.ord(a.status_id)=4
       and a.id is distinct from new.id;
   if new.amount > coalesce(lim,0) - used then
     raise exception 'amount exceeds remaining company funding limit (limit %, already approved %)', coalesce(lim,0), used; end if;
 end if;
 if n in (4,5) and nullif(btrim(coalesce(new.verdict,'')),'') is null then
   raise exception 'expert verdict is required to approve or reject'; end if;
 return new; end $function$;
